import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Tiles,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  Select,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const STATUS_OPTIONS: [string, string][] = [
  ['신청', '신청'],
  ['마감', '마감'],
  ['마감취소', '마감취소'],
  ['승인', '승인'],
  ['승인취소', '승인취소'],
];

export default function FnSfr03210Page({ role, notify }: PageProps) {
  const [accountingUnit, setAccountingUnit] = useState('');
  const [fiscalYear, setFiscalYear] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);

  const [checkOpen, setCheckOpen] = useState(false);
  const [checkProject, setCheckProject] = useState<number | string>('');
  const [checkAmount, setCheckAmount] = useState<number | string>('');
  const [checkRows, setCheckRows] = useState<Row[] | undefined>(undefined);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/main-budgets', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const rows = data?.items ?? [];
  const pageSum = rows.reduce((sum, r) => sum + Number(r['requestAmount'] ?? 0), 0);

  function search() {
    setPage(0);
    setApplied({ accountingUnit, fiscalYear, projectId, status });
  }

  function reset() {
    setAccountingUnit('');
    setFiscalYear('');
    setProjectId('');
    setStatus('');
    setPage(0);
    setApplied({});
  }

  function openCheck() {
    setCheckProject('');
    setCheckAmount('');
    setCheckRows(undefined);
    setCheckOpen(true);
  }

  async function runCheck() {
    if (checkProject === '') {
      throw new Error('프로젝트를 선택해 주세요.');
    }
    if (checkAmount === '' || typeof checkAmount !== 'number' || checkAmount < 0) {
      throw new Error('요청 금액은 0 이상의 숫자로 입력해 주세요.');
    }
    const res = await call<Page>('GET', '/main-budgets', role, undefined, { projectId: checkProject, size: 200 });
    if (res.items.length === 0) {
      setCheckRows(undefined);
      throw new Error('예산이 편성되어 있지 않아 진행할 수 없습니다.');
    }
    setCheckRows(res.items);
    notify('예산을 조회했습니다.');
  }

  // 가정: 승인된 본예산의 신청금액 합계를 예산액으로 본다.
  const approvedSum = (checkRows ?? [])
    .filter((r) => r['status'] === '승인')
    .reduce((sum, r) => sum + Number(r['requestAmount'] ?? 0), 0);

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>예산 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['이 쪽 신청금액 합계', <Num value={pageSum} />],
          ]}
        />
      </section>
      <section className='box span-12'>
        <h2>본예산 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='회계단위'>
            <TextInput value={accountingUnit} onChange={setAccountingUnit} />
          </Field>
          <Field label='기수(회계연도)'>
            <NumberInput value={fiscalYear} onChange={setFiscalYear} />
          </Field>
          <Field label='프로젝트'>
            <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} />
          </Field>
          <Field label='상태'>
            <Select value={status} onChange={setStatus} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type='button' onClick={openCheck}>예산 통제 확인</button>
        </Band>
        {error ? <div>{error}</div> : null}
        {loading ? <div>불러오는 중…</div> : null}
        <DataTable
          rows={rows}
          empty='조회된 예산이 없습니다.'
          columns={[
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r['projectId']} /> },
            { key: 'budgetItemId', label: '예산과목', render: (r) => <RefName table='budget_item' role={role} value={r['budgetItemId']} /> },
            { key: 'accountingUnit', label: '회계단위' },
            { key: 'fiscalYear', label: '기수(회계연도)' },
            { key: 'requestAmount', label: '신청금액', render: (r) => <Num value={r['requestAmount']} /> },
            { key: 'status', label: '상태', render: (r) => <Badge value={r['status']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {checkOpen ? (
        <Drawer title='예산 조회 및 통제 확인' onClose={() => setCheckOpen(false)}>
          <Form onSubmit={runCheck} submit='조회'>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={checkProject} onChange={setCheckProject} />
            </Field>
            <Field label='요청 금액' required>
              <NumberInput value={checkAmount} onChange={setCheckAmount} />
            </Field>
          </Form>
          {checkRows ? (
            <Pairs
              items={[
                ['편성된 예산 건수', <Num value={checkRows.length} />],
                ['예산액(승인 본예산 신청금액 합계)', <Num value={approvedSum} />],
                ['요청 금액', <Num value={checkAmount} />],
              ]}
            />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
